% ========================================================================
%  File: sensor_simulator.m
%  Purpose: Simulate accelerometer measurements of vibration signals
%           generated by the bearing damage model.
% ========================================================================

function varargout = sensor_simulator(action, varargin)

switch lower(action)
    case 'measure'
        [varargout{1}, varargout{2}] = simulate_measurement(varargin{:});
    case 'sample_rate'
        varargout{1} = varargin{1}.sensor.Fs;
    otherwise
        error('sensor_simulator: unknown action "%s"', action);
end

end



%% ========================================================================
%  MAIN MEASUREMENT SIMULATION
% ========================================================================

function [x_measured, info] = simulate_measurement(state, cfg, seed)

if nargin < 3 || isempty(seed)
    seed = round(state.t_hours * 1000) + 1;
end
rng(seed, 'twister');

Fs = cfg.sensor.Fs;
N  = cfg.sensor.window_samples;
t  = (0:N-1).' / Fs;

amps = motor_model('vibration_amplitudes', state, cfg);

fr       = cfg.machine.rot_freq_Hz;
f_BPFO_p = cfg.fault_freq.primary.BPFO;
f_BPFI_p = cfg.fault_freq.primary.BPFI;
f_BPFO_s = cfg.fault_freq.secondary.BPFO;
f_BPFI_s = cfg.fault_freq.secondary.BPFI;

% Shaft Rotational Harmonics
x_rotation = zeros(N, 1);
for k = 1:3
    A_k   = amps.A_1x / k;
    phi_k = 2 * pi * rand;
    x_rotation = x_rotation + A_k * sin(2 * pi * k * fr * t + phi_k);
end

% Primary Bearing: BPFO (Outer Race)
phi_BPFO_p = 2 * pi * rand;
x_BPFO_primary = amps.A_BPFO_primary * sin(2 * pi * f_BPFO_p * t + phi_BPFO_p);

% Primary Bearing: BPFI (Inner Race)
m_BPFI_p = 0.5;
phi_carrier_p = 2 * pi * rand;
phi_mod_p     = 2 * pi * rand;

modulation_p = 1 + m_BPFI_p * cos(2 * pi * fr * t + phi_mod_p);
x_BPFI_primary = amps.A_BPFI_primary * modulation_p .* ...
                 sin(2 * pi * f_BPFI_p * t + phi_carrier_p);

% Secondary Bearing: BPFO
phi_BPFO_s = 2 * pi * rand;
x_BPFO_secondary = amps.A_BPFO_secondary * sin(2 * pi * f_BPFO_s * t + phi_BPFO_s);

% Secondary Bearing: BPFI
m_BPFI_s = 0.5;
phi_carrier_s = 2 * pi * rand;
phi_mod_s     = 2 * pi * rand;

modulation_s = 1 + m_BPFI_s * cos(2 * pi * fr * t + phi_mod_s);
x_BPFI_secondary = amps.A_BPFI_secondary * modulation_s .* ...
                   sin(2 * pi * f_BPFI_s * t + phi_carrier_s);

f_res = cfg.resonance.freq_Hz;
m_res = cfg.resonance.modulation_depth;
D_now = state.D_total;

% Amplitude grows NONLINEARLY with damage — spall impacts are sharp
A_res = cfg.resonance.A_healthy_g * ...
    (1 + cfg.resonance.k_defect * D_now ^ cfg.resonance.gamma_defect);

% Primary bearing resonance — modulated by BPFO
phi_res_1 = 2*pi*rand;
phi_mod_1 = 2*pi*rand;
x_res_BPFO_primary = A_res * ...
    (1 + m_res * cos(2*pi*f_BPFO_p*t + phi_mod_1)) .* ...
    sin(2*pi*f_res*t + phi_res_1);

% Primary bearing resonance — modulated by BPFI
phi_res_2 = 2*pi*rand;
phi_mod_2 = 2*pi*rand;
x_res_BPFI_primary = A_res * 0.7 * ...
    (1 + m_res * cos(2*pi*f_BPFI_p*t + phi_mod_2)) .* ...
    sin(2*pi*f_res*t + phi_res_2);

% Total resonance component
x_resonance = x_res_BPFO_primary + x_res_BPFI_primary;

% Broadband Noise Floor
x_broadband = amps.A_noise * randn(N, 1);

% Sensor Electronics Noise
x_sensor_noise = cfg.sensor.noise_std * randn(N, 1);

% Signal Superposition
x_clean = x_rotation ...
        + x_BPFO_primary ...
        + x_BPFI_primary ...
        + x_BPFO_secondary ...
        + x_BPFI_secondary ...
        + x_resonance ... 
        + x_broadband;

x_with_sensor_noise = x_clean + x_sensor_noise;

% Accelerometer Saturation Limits
x_measured = x_with_sensor_noise;
x_measured(x_measured > cfg.sensor.saturation_max) = cfg.sensor.saturation_max;
x_measured(x_measured < cfg.sensor.saturation_min) = cfg.sensor.saturation_min;

% Diagnostic Info
info.t                  = t;
info.x_rotation         = x_rotation;
info.x_BPFO_primary     = x_BPFO_primary;
info.x_BPFI_primary     = x_BPFI_primary;
info.x_BPFO_secondary   = x_BPFO_secondary;
info.x_BPFI_secondary   = x_BPFI_secondary;
info.x_resonance        = x_resonance;
info.x_broadband        = x_broadband;
info.x_sensor_noise     = x_sensor_noise;
info.x_clean            = x_clean;
info.D_total            = state.D_total;
info.seed               = seed;

info.rms_total          = rms(x_measured);
info.rms_clean          = rms(x_clean);
info.rms_sensor_noise   = rms(x_sensor_noise);
info.snr_dB             = 20 * log10(info.rms_clean / info.rms_sensor_noise);

end